 simpleKeys.forEach(k=>{const i=document.createElement('input');i.value=x[k]??'';if(['width','thickness','coreDiameter'].includes(k)){i.type='number';i.step='any'}inputs[k]=i;wrap.append(['width','thickness','coreDiameter'].includes(k)?smartNumberField(tr(k),i):stackField(tr(k),i))});
 // Stock always remains visible. Existing stock starts read-only and can be unlocked with the independent inventory password.
 const stock=document.createElement('input');stock.type='number';stock.step='any';stock.value=metersToDisplay(Number(x.stock)||0);inputs.stock=stock;
 if(existing){stock.disabled=!stockUnlocked;const row=document.createElement('label');row.className='smart-field stock-edit-field';const cap=document.createElement('span');cap.textContent=`${tr('stock')} (${inventoryUnit()})`;const line=document.createElement('div');line.className='smart-number stock-lock-row';const unlockBtn=btn(lang==='zh'?'🔒 解锁':'🔒 Unlock',async()=>{if(!can('setBalance'))return toast(lang==='zh'?'没有直接修改库存的权限。':'Set balance permission required.');const ok=await inventoryAuth(true);if(!ok)return;stockUnlocked=true;stock.disabled=false;line.classList.add('unlocked');unlockBtn.textContent=lang==='zh'?'🔓 已解锁':'🔓 Unlocked';stock.focus()},'stock-unlock');unlockBtn.type='button';line.append(stock,unlockBtn);row.append(cap,line);wrap.append(row)}else wrap.append(smartNumberField(`${tr('stock')} (${inventoryUnit()})`,stock));
 const min=document.createElement('input');min.type='number';min.step='any';min.value=metersToDisplay(Number(x.minStock)||0);inputs.minimumStock=min;wrap.append(smartNumberField(`${tr('minimumStock')} (${inventoryUnit()})`,min));
