function renderSettings(){$('protectionToggle').textContent=data.settings.passwordProtection?tr('on'):tr('off');$('protectionToggle').className='toggle-button '+(data.settings.passwordProtection?'on':'off');$('adminTimeoutSelect').value=['0','1','5','10','15','30'].includes(String(data.settings.adminTimeoutMinutes))?String(data.settings.adminTimeoutMinutes):'custom';$('deviceUnlockBtn').textContent=data.settings.deviceCredentialId?tr('disableDeviceUnlock'):tr('enableDeviceUnlock');$('autoBackupToggle').textContent=data.settings.autoBackup?tr('on'):tr('off');$('autoBackupToggle').className='toggle-button '+(data.settings.autoBackup?'on':'off');$('backupSchedule').style.opacity=data.settings.autoBackup?'1':'.5';$('lastBackup').textContent=data.settings.lastBackup?new Date(data.settings.lastBackup).toLocaleString():'—';$('nextBackup').textContent=nextBackupText();$('backupDestinationNote').textContent=tr('destinationNote');updateAuthStatus();$('backupInventory').checked=data.settings.backupInventory!==false;$('backupSettings').checked=data.settings.backupSettings!==false;renderBackupHistory();updateAuthStatus()}
