function backupPayload(type){const now=new Date().toISOString();if(type==='inventory')return{product:'Belt Roll Calculator',type:'inventory',build:BUILD,created:now,data:{belts:structuredClone(data.belts),history:structuredClone(data.history)}};return{product:'Belt Roll Calculator',type:'settings',build:BUILD,created:now,data:{users:structuredClone(data.users),settings:structuredClone(data.settings),calcHistory:structuredClone(data.calcHistory||[]),convHistory:structuredClone(data.convHistory||[])}}}
function canBackup(){return cloudProfile()?window.BRCCloud?.can?.('backup')!==false:true}
function canRestoreBackup(){return cloudProfile()?!!window.BRCCloud?.can?.('restoreBackup'):isAdmin()}
function createInternalBackup(reason='manual',types=null){try{const selected=types||[data.settings.backupInventory!==false?'inventory':null,data.settings.backupSettings!==false?'settings':null].filter(Boolean);if(!selected.length)return toast(lang==='zh'?'请至少选择一种备份。':'Select at least one backup type.');const snaps=selected.map(type=>{const payload=backupPayload(type),snap={id:uid('backup'),date:payload.created,reason,type,payload};data.backups.push(snap);return snap});const keep=Math.max(1,Number(data.settings.backupRetention)||30);if(data.backups.length>keep*2)data.backups=data.backups.slice(-(keep*2));data.settings.lastBackup=snaps[snaps.length-1].date;data.history.push({id:uid('tx'),date:new Date().toISOString(),belt:'System',action:'backup-'+reason,user:user()?.name||tr('guest'),note:selected.join(', '),protected:true});localStorage.setItem(KEY,JSON.stringify(data));renderSettings();renderBackupHistory();renderHistory();return snaps}catch(e){console.error(e);toast(lang==='zh'?'备份失败。':'Backup failed.');return null}}
function backupBlob(payload){return new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})}
