function nextBackupText(){if(!data.settings.autoBackup)return '—';const f=data.settings.backupFrequency;if(f==='onChange')return tr('waitingChange');if(f==='onClose')return tr('onCloseText');const n=nextScheduledDate();return n?n.toLocaleString():'—'}
function nextScheduledDate(){const [h,m]=(data.settings.backupTime||'00:00').split(':').map(Number),now=new Date(),d=new Date(now);d.setSeconds(0,0);d.setHours(h,m,0,0);if(data.settings.backupFrequency==='daily'){if(d<=now)d.setDate(d.getDate()+1)}else if(data.settings.backupFrequency==='weekly'){let add=(Number(data.settings.backupDay)-d.getDay()+7)%7;if(add===0&&d<=now)add=7;d.setDate(d.getDate()+add)}else if(data.settings.backupFrequency==='monthly'){d.setDate(Math.min(Number(data.settings.backupDate),new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));if(d<=now){d.setMonth(d.getMonth()+1,1);d.setDate(Math.min(Number(data.settings.backupDate),new Date(d.getFullYear(),d.getMonth()+1,0).getDate()))}}return d}
function checkScheduledBackup(){if(!data.settings.autoBackup||!['daily','weekly','monthly'].includes(data.settings.backupFrequency))return;const last=data.settings.lastBackup?new Date(data.settings.lastBackup):new Date(0),next=nextScheduledDate();const due=new Date(next);if(next>Date.now())due.setDate(due.getDate()-(data.settings.backupFrequency==='daily'?1:data.settings.backupFrequency==='weekly'?7:0));if(data.settings.backupFrequency==='monthly')due.setMonth(due.getMonth()-1);if(last<due)createInternalBackup('scheduled')}
