function convert(record=false){const cat=$('convCategory').value,a=$('convFrom').value,b=$('convTo').value,n=+$('convInput').value;if(!Number.isFinite(n)){ $('convToValue').value='—';$('convOutput').textContent='';return }let out;if(cat==='temperature'){const toC=a==='°C'?n:a==='°F'?(n-32)*5/9:n-273.15;out=b==='°C'?toC:b==='°F'?toC*9/5+32:toC+273.15}else out=n*conv[cat].units[a]/conv[cat].units[b];$('convToValue').value=fmt(out);$('convOutput').textContent=cat==='length'&&b==='ft'?`${Math.floor(out)} ft ${fmt((out-Math.floor(out))*12)} in`:'';if(record){data.convHistory=data.convHistory||[];data.convHistory.push({date:new Date().toISOString(),cat,from:a,to:b,input:n,output:out});data.convHistory=data.convHistory.slice(-100);save();renderConvHistory()}}
