function renderCalcHistory(){const box=$('calcHistoryList');if(!box)return;box.innerHTML=(data.calcHistory||[]).slice().reverse().map((x,i)=>`<button class="calc-history-item" data-ch="${data.calcHistory.length-1-i}"><span>${esc(x.expression)}</span><b>${esc(x.result)}</b></button>`).join('')||`<div class="muted">${tr('empty')}</div>`;document.querySelectorAll('[data-ch]').forEach(b=>b.onclick=()=>{calcExpr=data.calcHistory[+b.dataset.ch].result;$('deskDisplay').textContent=calcExpr})}
function factorial(n){if(!Number.isInteger(n)||n<0||n>170)throw 0;let r=1;for(let i=2;i<=n;i++)r*=i;return r}
function currentValue(){const safe=calcExpr.replaceAll('×','*').replaceAll('÷','/').replaceAll('−','-').replaceAll('π',String(Math.PI)).replace(/\be\b/g,String(Math.E));if(!/^[0-9eE+\-*/().\s]+$/.test(safe))throw 0;return Function(`"use strict";return (${safe})`)()}
function unary(label,fn){const before=calcExpr,value=fn(Number(currentValue()));if(!Number.isFinite(value))throw 0;calcExpr=String(value);return `${label}(${before})`}
function deskKey(k){const display=$('deskDisplay');try{
 let historyExpression='';
 if(k==='MC')memory=0;
 else if(k==='MR')calcExpr=String(memory);
 else if(k==='M+')memory+=Number(currentValue())||0;
 else if(k==='M-')memory-=Number(currentValue())||0;
 else if(k==='C')calcExpr='0';
 else if(k==='CE'){calcExpr=calcExpr.replace(/(?:\d*\.?\d+(?:e[+\-]?\d+)?)$/i,'')||'0'}
 else if(k==='⌫')calcExpr=calcExpr.length>1?calcExpr.slice(0,-1):'0';
 else if(k==='+/−')historyExpression=unary('neg',x=>-x);
 else if(k==='%')historyExpression=unary('%',x=>x/100);
 else if(k==='√')historyExpression=unary('√',Math.sqrt);
 else if(k==='x²')historyExpression=unary('sqr',x=>x*x);
 else if(k==='1/x')historyExpression=unary('recip',x=>1/x);
 else if(k==='n!')historyExpression=unary('fact',factorial);
 else if(k==='sin'||k==='cos'||k==='tan'){const f=Math[k],factor=angleUnit==='DEG'?Math.PI/180:1;historyExpression=unary(k,x=>f(x*factor))}
 else if(k==='asin'||k==='acos'||k==='atan'){const f=Math[k],factor=angleUnit==='DEG'?180/Math.PI:1;historyExpression=unary(k,x=>f(x)*factor)}
 else if(k==='ln')historyExpression=unary('ln',Math.log);
 else if(k==='log')historyExpression=unary('log',Math.log10);
 else if(k==='10ˣ')historyExpression=unary('10^',x=>10**x);
 else if(k==='π')calcExpr=calcExpr==='0'?String(Math.PI):calcExpr+String(Math.PI);
 else if(k==='e')calcExpr=calcExpr==='0'?String(Math.E):calcExpr+String(Math.E);
 else if(k==='xʸ')calcExpr+='^';
 else if(k==='EXP')calcExpr+='e';
 else if(k==='Ans'){const h=data.calcHistory||[];calcExpr=h.length?h[h.length-1].result:calcExpr}
 else if(k==='2nd'){}
 else if(k==='='){const expression=calcExpr.replaceAll('^','**'),safe=expression.replaceAll('×','*').replaceAll('÷','/').replaceAll('−','-');if(!/^[0-9eE+\-*/().\s*]+$/.test(safe))throw 0;const result=String(Function(`"use strict";return (${safe})`)());if(!Number.isFinite(Number(result)))throw 0;calcExpr=result;data.calcHistory=data.calcHistory||[];data.calcHistory.push({date:new Date().toISOString(),expression:`${expression} =`,result});data.calcHistory=data.calcHistory.slice(-100);save();renderCalcHistory()}
 else{if(k==='duplicate-zero')return;if(calcExpr==='0'&&/\d/.test(k))calcExpr=k;else calcExpr+=k}
 if(historyExpression){data.calcHistory=data.calcHistory||[];data.calcHistory.push({date:new Date().toISOString(),expression:`${historyExpression} =`,result:calcExpr});data.calcHistory=data.calcHistory.slice(-100);save();renderCalcHistory()}
 display.textContent=calcExpr
 }catch{display.textContent='Error'}
}
