function renderCloudQuick(){const b=$('cloudQuickStatus');if(!b)return;const st=window.BRCCloud?.state||{status:'signed-out'};const ok=['connected','migration-needed'].includes(st.status),busy=['syncing','connecting','recovery'].includes(st.status),bad=['error','offline','library-error'].includes(st.status);b.className=`cloud-quick ${ok?'ok':busy?'busy':bad?'bad':''}`;b.querySelector('span').textContent=ok?(lang==='zh'?'云端':'Cloud'):st.status==='offline'?(lang==='zh'?'离线':'Offline'):busy?(lang==='zh'?'同步中':'Syncing'):bad?(lang==='zh'?'错误':'Error'):(lang==='zh'?'云端':'Cloud');b.title=st.error||st.status}
function renderCloudPanel(){
 const box=$('cloudPanel');if(!box)return;const st=window.BRCCloud?.state||{status:'signed-out'},zh=lang==='zh';
 const statusLabels={connected:zh?'云端已连接':'Cloud Connected',syncing:zh?'正在同步':'Syncing',error:zh?'同步错误':'Sync Error','signed-out':zh?'尚未登录':'Signed Out',connecting:zh?'正在连接':'Connecting','library-error':zh?'云端组件加载失败':'Cloud Library Error','migration-needed':zh?'等待上传本地库存':'Local Inventory Ready','offline':zh?'离线模式':'Offline',recovery:zh?'密码重设模式':'Password Recovery'};
 const cls=st.status==='connected'?'ok':st.status==='syncing'||st.status==='connecting'||st.status==='migration-needed'||st.status==='recovery'?'busy':st.status==='error'?'bad':'off';
 box.innerHTML=`<div class="cloud-head"><div><h3>${zh?'云端同步':'Cloud Sync'} <span class="beta-pill">BETA</span></h3><small>${zh?'Mac、iPad、Windows 和 iPhone 共用同一份库存。':'Use one shared inventory on Mac, iPad, Windows, and iPhone.'}</small></div><b class="cloud-status ${cls}"><i></i>${statusLabels[st.status]||st.status}</b></div>
 <div class="cloud-fixed"><div><span>${zh?'服务器':'Server'}</span><b>DCZ Cloud</b></div><div><span>${zh?'项目':'Project'}</span><b>belt-roll-calculator</b></div><div><span>Region</span><b>US West</b></div></div>
 ${st.user?`<div class="actions">${st.status==='migration-needed'?`<button id="cloudMigrate" class="primary">${tr('cloudMigration')}</button>`:''}<button id="cloudReload">${zh?'立即同步':'Sync Now'}</button><button id="cloudLogout">${zh?'退出云端':'Cloud Sign Out'}</button></div>`:`<div class="cloud-grid auth-only"><label>Email</label><input id="cloudEmail" type="email" autocomplete="username"><label>${zh?'密码':'Password'}</label><input id="cloudPassword" type="password" autocomplete="current-password"></div><div class="actions"><button id="cloudLogin" class="primary">${zh?'登录云端':'Cloud Sign In'}</button><button id="cloudForgot">${zh?'忘记密码':'Forgot Password'}</button></div>`}
 <small class="muted">${st.user?`${zh?'已登录':'Signed in'}: ${esc(st.user.email||'')} · ${zh?'最近同步':'Last sync'}: ${st.lastSync?new Date(st.lastSync).toLocaleString():'—'}`:(zh?'Cloud 连接资料已内置，只需使用 Supabase 用户邮箱和密码登录。':'Cloud connection settings are built in. Sign in with your Supabase email and password.')}${st.error?`<br><span class="cloud-error">${esc(st.error)}</span>`:''}</small>`;
 if($('cloudLogin'))$('cloudLogin').onclick=async()=>{try{await window.BRCCloud.signIn($('cloudEmail').value,$('cloudPassword').value);renderCloudPanel()}catch(e){toast(e.message)}};
 if($('cloudForgot'))$('cloudForgot').onclick=async()=>{try{await window.BRCCloud.requestPasswordReset($('cloudEmail').value);toast(zh?'密码重设邮件已发送。':'Password recovery email sent.')}catch(e){toast(e.message)}};
 if($('cloudLogout'))$('cloudLogout').onclick=()=>window.BRCCloud.signOut().then(renderCloudPanel);
 if($('cloudMigrate'))$('cloudMigrate').onclick=()=>window.BRCCloud.pushLocalToCloud().then(()=>toast(zh?'本地库存已上传。':'Local inventory uploaded.')).catch(e=>toast(e.message));
 if($('cloudReload'))$('cloudReload').onclick=()=>window.BRCCloud.loadCloud().then(()=>toast(zh?'云端同步完成。':'Cloud sync complete.')).catch(e=>toast(e.message));
}
