function maybeOpenPasswordRecovery(){
 const st=window.BRCCloud?.state;if(!st?.recovery||recoveryModalOpen)return;
 recoveryModalOpen=true;const zh=lang==='zh',wrap=document.createElement('div'),p1=document.createElement('input'),p2=document.createElement('input');wrap.className='form-stack';p1.type=p2.type='password';p1.autocomplete='new-password';p2.autocomplete='new-password';wrap.append(stackField(zh?'新密码':'New Password',p1),stackField(zh?'确认新密码':'Confirm Password',p2));
 openModal(zh?'重设云端密码':'Reset Cloud Password',wrap,[btn(tr('cancel'),()=>{recoveryModalOpen=false;window.BRCCloud?.endRecovery?.();closeModal()}),btn(tr('save'),async()=>{if(p1.value!==p2.value)return toast(zh?'两次密码输入不一致。':'Passwords do not match.');try{await window.BRCCloud.updatePassword(p1.value);recoveryModalOpen=false;closeModal();toast(zh?'密码已更新，请使用新密码登录。':'Password updated. You can now sign in with the new password.');await window.BRCCloud.signOut()}catch(e){toast(e.message)}},'primary')]);
}
